sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
	gs.addInfoMessage(gs.getMessage("x_hccc_hoc_ohs.document_has_been_copied"));
	// check if investigation case have a parent

	var destinationRecord;
	var parentCase = new GlideRecord("x_hccc_hoc_ohs_investigation_case");
	var parentFound=parentCase.get(current.document.parent);

	if(parentFound){
		destinationRecord=parentCase.getValue("sys_id");
	}else{
		destinationRecord=current.document.sys_id;
	}

    //gs.sleep(5000); //5 seconds //Sleep doesn't work when not global
	//var globalSleep = new global.HoCSleepFunction(); //
	//globalSleep.sleep(5000); //Needs cross scope access privilege

    var copyAtt = new GlideSysAttachment();

    copyAtt.copy("pdf_draft", current.sys_id, "x_hccc_hoc_ohs_investigation_case", destinationRecord);

})(current, previous);
